def choose_move(observation):
    def clamp_dir(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            try:
                return int(value[0]), int(value[1])
            except Exception:
                return default
        return default

    def grid_size():
        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        try:
            w = int(w)
        except Exception:
            w = 0
        try:
            h = int(h)
        except Exception:
            h = 0
        return w, h

    def move_toward(src, dst):
        return [clamp_dir(dst[0] - src[0]), clamp_dir(dst[1] - src[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_by_distance(items, src, prefer_far=False):
        best_item = None
        best_score = None
        for item in items:
            p = pos(item, None)
            if p is None:
                continue
            d = manhattan(src, p)
            score = -d if prefer_far else d
            if best_score is None or score < best_score:
                best_score = score
                best_item = p
        return best_item

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    me = (sx, sy)
    opp = (ox, oy)
    w, h = grid_size()

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_toward(me, opp)
        corners = [(0, 0), (0, max(0, h - 1)), (max(0, w - 1), 0), (max(0, w - 1), max(0, h - 1))]
        target = best_by_distance(corners, opp, prefer_far=True)
        if target is None:
            target = (0, 0)
        return move_toward(me, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("enemy_territory") or []
        target = best_by_distance(targets, me, prefer_far=False)
        if target is None:
            if w > 0 and h > 0:
                target = (w // 2, h // 2)
            else:
                target = opp
        return move_toward(me, target)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_by_distance(resources, me, prefer_far=False)
    if target is None:
        if w > 0 and h > 0:
            target = (w // 2, h // 2)
        else:
            target = opp
    return move_toward(me, target)

